/* Reads the public TGJU snapshot generated by GitHub Actions. */
(()=>{'use strict';
const DATA_URL='./data/market-rates.json',STALE_AFTER=15*60*1000;
const ITEMS=[
 {key:'usd',id:'priceUsd',timeId:'timeUsd',unit:'تومان',irr:true},
 {key:'eur',id:'priceEur',timeId:'timeEur',unit:'تومان',irr:true},
 {key:'gold',id:'priceGold',timeId:'timeGold',unit:'تومان / گرم',irr:true},
 {key:'oil',id:'priceOil',timeId:'timeOil',unit:'دلار / بشکه',irr:false}
];
const el=id=>document.getElementById(id),fmt=n=>new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2}).format(n);
function dateLabel(value){if(!value)return '';const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';return new Intl.DateTimeFormat('fa-IR',{timeZone:'Asia/Tehran',year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}
function render(item,row){
 const priceEl=el(item.id),timeEl=el(item.timeId);if(!priceEl||!timeEl)return false;
 const raw=Number(row&&row.price);
 if(!Number.isFinite(raw)||raw<=0){priceEl.textContent='—';if(priceEl.nextElementSibling)priceEl.nextElementSibling.textContent=item.unit;timeEl.textContent='هنوز داده‌ای از TGJU ثبت نشده';timeEl.dataset.stale='true';return false}
 const price=item.irr?raw/10:raw;
 priceEl.textContent=fmt(price);if(priceEl.nextElementSibling)priceEl.nextElementSibling.textContent=item.unit;
 const fetched=row.fetchedAt?new Date(row.fetchedAt):null,age=fetched&&Number.isFinite(fetched.getTime())?Date.now()-fetched.getTime():Infinity;
 const stale=Boolean(row.stale)||age<0||age>STALE_AFTER,received=dateLabel(row.fetchedAt);
 timeEl.textContent=(stale?'هشدار: قیمت قدیمی':'منبع: TGJU')+(received?' · دریافت: '+received:'')+(row.sourceDate?' · تاریخ ثبت در TGJU: '+row.sourceDate:'');
 timeEl.dataset.stale=String(stale);timeEl.title=row.sourceUrl?'منبع قیمت: '+row.sourceUrl:'منبع قیمت: TGJU';
 return true;
}
async function fetchMarketCurrencies(){
 try{
  const response=await fetch(DATA_URL,{cache:'no-store',headers:{Accept:'application/json'}});
  if(!response.ok)throw new Error('HTTP '+response.status);
  const data=await response.json(),items=data.items||{};
  let valid=0,stale=0;
  for(const item of ITEMS){const row=items[item.key];if(render(item,row)){valid++;const fetched=Date.parse(row.fetchedAt);if(Boolean(row.stale)||!Number.isFinite(fetched)||Date.now()-fetched<0||Date.now()-fetched>STALE_AFTER)stale++}}
  const gbp=document.getElementById('priceGbp'),gbpTime=document.getElementById('timeGbp');
  if(gbp){gbp.textContent='—';if(gbp.nextElementSibling)gbp.nextElementSibling.textContent='تومان'}
  if(gbpTime){gbpTime.textContent='در این نسخه از منبع TGJU دریافت نمی‌شود';gbpTime.dataset.stale='true'}
  const status=el('marketStatus');
  if(status){const checked=dateLabel(data.checkedAt);status.textContent=valid===0?'قیمت‌ها هنوز دریافت نشده‌اند؛ اجرای GitHub Actions را بررسی کنید.':'منبع: TGJU مستقیم · داده موجود: '+valid+'/4'+(stale?' · هشدار: '+stale+' قیمت قدیمی':'')+(checked?' · آخرین بررسی: '+checked:'')}
  return {valid,stale,errors:4-valid,checkedAt:data.checkedAt};
 }catch(error){
  for(const item of ITEMS){const time=el(item.timeId);if(time){time.dataset.stale='true';time.textContent='هشدار: دریافت داده ناموفق بود'}}
  const status=el('marketStatus');if(status)status.textContent='دریافت فایل قیمت ناموفق بود؛ اتصال یا اجرای GitHub Actions را بررسی کنید.';
  return {valid:0,errors:4,error:String(error)};
 }
}
window.fetchMarketCurrencies=fetchMarketCurrencies;
document.addEventListener('DOMContentLoaded',fetchMarketCurrencies,{once:true});
setInterval(fetchMarketCurrencies,5*60*1000);
})();